16	  if (!identifier || !/^[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*){2,}$/.test(identifier)) {
17	    throw new Error('APP_IDENTIFIER in .env must be an explicit reverse-domain Android package identifier.');
18	  }
19	  const reserved = new Set(['example', 'test', 'testing', 'placeholder', 'your', 'yourcompany', 'yourdomain']);
20	  const javaKeywords = new Set(['abstract', 'assert', 'boolean', 'break', 'byte', 'case', 'catch', 'char', 'class', 'const', 'continue', 'default', 'do', 'double', 'else', 'enum', 'extends', 'final', 'finally', 'float', 'for', 'goto', 'if', 'implements', 'import', 'instanceof', 'int', 'interface', 'long', 'native', 'new', 'package', 'private', 'protected', 'public', 'return', 'short', 'static', 'strictfp', 'super', 'switch', 'synchronized', 'this', 'throw', 'throws', 'transient', 'try', 'void', 'volatile', 'while', 'true', 'false', 'null']);
21	  if (identifier.split('.').some(segment => reserved.has(segment) || javaKeywords.has(segment))) {
